class TsharkMessages(object):
    def __init__(self):
        self._xml_instance = XML(use_lxml=True)

    def start_counting_packets_and_wait_for_given_packets_number(
        self, nr_of_packets, alias, timeout='10', packet_filter='', pdml=False, output_filepath=None
    ):
        """
        :param nr_of_packets:
        :param alias:
        :param timeout:
        :param packet_filter:
        :param pdml: convert to pdml
        :return:
        """
        logger.console(
            "Start counting {} packets, wait for {} for {} on alias {}".format(
                packet_filter, nr_of_packets, timeout, alias
            )
        )
        ute_tshark_instance = BuiltIn().get_library_instance('ute_tshark')
        try:
            ute_tshark_instance.start_counting_packets(packet_filter=packet_filter, alias=alias)
            ute_tshark_instance.wait_for_given_packets_number(packet_number=nr_of_packets, timeout=timeout, alias=alias)
        finally:
            ute_tshark_instance.stop_counting_packets(alias=alias)
        if pdml:
            ute_tshark_instance.stop_capturing(alias=alias)
            self.convert_tshark_to_pdml(alias=alias, packet_filter=packet_filter, output_filepath=output_filepath)

    def start_counting_packets_and_expect_no_packets_in_given_time(self, alias, timeout='10', packet_filter=''):
        """
        :param alias:
        :param timeout:
        :param packet_filter:
        :return:
        """
        logger.console("Start counting {} packets, wait for {} on alias {}".format(packet_filter, timeout, alias))
        ute_tshark_instance = BuiltIn().get_library_instance('ute_tshark')
        ute_tshark_instance.start_counting_packets(packet_filter=packet_filter, alias=alias)
        self.expect_no_packets_in_given_time(alias=alias, time=timeout)
        ute_tshark_instance.stop_counting_packets(alias=alias)

    def convert_tshark_to_pdml(self, alias, packet_filter, output_filepath, pcap_file_path=None):
        """
        :param alias:
        :param packet_filter:
        :param output_filepath:
        :return:
        """
        if pcap_file_path == 'default':
            pcap_file_path = TsharkVerify()._set_default_file_path(pcap_file_path=pcap_file_path)
        ute_tshark_instance = BuiltIn().get_library_instance('ute_tshark')
        logs = ute_tshark_instance.read_pcap(packet_filter=packet_filter, output_type='pdml', alias=alias, pcap_file_path=pcap_file_path)
        OperatingSystem().create_file(path=output_filepath, content=logs)
        return output_filepath

    def perform_ue_entry_and_wait_for_tshark_message(self, entry_command, ue_id, packet_filter, alias):
        """
        :param entry_command:
        :param ue_id:
        :param packet_filter:
        :param alias:
        :return:
        """
        logger.warn(
            "Please use Perform Ue Action And Wait For Given Tshark Message Number keyword instead of this keyword"
        )
        ute_tshark_instance = BuiltIn().get_library_instance('ute_tshark')
        ute_tshark_instance.start_counting_packets(
            packet_filter="{} && iphy.ue_id == {}".format(packet_filter, ue_id), alias=alias
        )
        BuiltIn().get_library_instance('ute_wtssim').execute_egate_command("{} id={}".format(entry_command, ue_id))
        ute_tshark_instance.wait_for_given_packets_number(packet_number=1, timeout=15, alias=alias)
        ute_tshark_instance.stop_counting_packets(alias=alias)

    def perform_ue_action_and_wait_for_given_tshark_message_number(
        self, alias, packet_filter, action, packet_number='1', waiting_timeout=60, **kwargs
    ):
        """
        Keyword for Robot Framework 2.9
        Please use this keyword instead of Perform Ue Entry And Wait For Tshark Message
        'Action' argument expects keyword.
        """
        self.perform_action_and_wait_for_given_tshark_message_number(
            alias=alias,
            packet_filter="{} && iphy.ue_id == {}".format(packet_filter, kwargs.get('ue_id') or kwargs.get('ues')),
            packet_number=packet_number,
            action=action,
            waiting_timeout=waiting_timeout,
            **kwargs
        )

    def perform_action_and_wait_for_given_tshark_message_number(
        self, alias, packet_filter, action, packet_number='1', waiting_timeout=60, **kwargs
    ):
        """
        :param alias:
        :param packet_filter:
        :param action:
        :param packet_number:
        :param kwargs:
        :return:
        """
        kwargs_list = []
        for name, value in list(kwargs.items()):
            kwargs_list.append('{0}={1}'.format(name, value))
        ute_tshark_instance = BuiltIn().get_library_instance('ute_tshark')
        ute_tshark_instance.start_counting_packets(packet_filter=packet_filter, alias=alias)
        try:
            BuiltIn().run_keyword(action, *kwargs_list)
            ute_tshark_instance.wait_for_given_packets_number(
                packet_number=packet_number, timeout=waiting_timeout, alias=alias
            )
        finally:
            ute_tshark_instance.stop_counting_packets(alias=alias)

    def perform_action_and_wait_for_given_tshark_message_number_and_convert_to_pdml(
        self, packet_number, output_filepath, packet_filter, eth_interface, action, waiting_timeout=60, **kwargs
    ):
        """
        :param packet_number:
        :param output_filepath:
        :param packet_filter:
        :param eth_interface:
        :param action:
        :param kwargs:
        :return:
        """
        try:
            tshark_rrc_alias = TsharkStart().start_tshark_for_custom_interface(eth_interface=eth_interface)
            self.perform_action_and_wait_for_given_tshark_message_number(
                alias=tshark_rrc_alias,
                packet_filter=packet_filter,
                packet_number=packet_number,
                waiting_timeout=waiting_timeout,
                action=action,
                **kwargs
            )
            BuiltIn().get_library_instance('ute_tshark').stop_capturing(alias=tshark_rrc_alias)
            self.convert_tshark_to_pdml(
                alias=tshark_rrc_alias, packet_filter=packet_filter, output_filepath=output_filepath
            )
        finally:
            BuiltIn().get_library_instance('ute_tshark').teardown_tshark(alias=tshark_rrc_alias)

    def compare_elements_show_attribute_from_messages(self, first_pdml, second_pdml, first_xpath, second_xpath):
        """
        :param first_pdml:
        :param second_pdml:
        :param first_xpath:
        :param second_xpath:
        :return:
        """
        first_element_list = self._xml_instance.get_child_elements(source=first_pdml, xpath=first_xpath)
        second_element_list = self._xml_instance.get_child_elements(source=second_pdml, xpath=second_xpath)
        for first, second in zip(first_element_list, second_element_list):
            BuiltIn().should_be_equal(first.attrib['show'], second.attrib['show'])

    def check_tshark_message_for_atrribute(
        self, alias, filter, output_pdml_filepath, xpath, attribute, expected_attribute_value
    ):
        """
        :param alias:
        :param filter:
        :param output_pdml_filepath:
        :param xpath:
        :param attribute:
        :param expected_attribute_value:
        :return:
        """
        attribute_value = self.get_attribute_value_from_tshark_message(
            alias=alias, filter=filter, output_pdml_filepath=output_pdml_filepath, xpath=xpath, attribute=attribute
        )
        if attribute_value != expected_attribute_value:
            raise ExecutionFailed(
                message="{} {}  Should be equal".format(attribute_value, expected_attribute_value),
                continue_on_failure=True,
            )

    def check_tshark_message_for_absence_of_atrribute(
        self, alias, filter, output_pdml_filepath, xpath, expected_attribute_value
    ):
        """
        :param alias:
        :param filter:
        :param output_pdml_filepath:
        :param xpath:
        :param expected_attribute_value:
        :return:
        """
        self.convert_tshark_to_pdml(alias=alias, packet_filter=filter, output_filepath=output_pdml_filepath)
        attribute_value = self._xml_instance.get_element_attributes(source=output_pdml_filepath, xpath=xpath)
        self._xml_instance.element_should_not_have_attribute(source=attribute_value, name=expected_attribute_value)

    def check_tshark_message_for_absence_of_element(self, alias, filter, output_pdml_filepath, xpath):
        """
        :param alias:
        :param filter:
        :param output_pdml_filepath:
        :param xpath:
        :return:
        """
        self.convert_tshark_to_pdml(alias=alias, packet_filter=filter, output_filepath=output_pdml_filepath)
        self._xml_instance.element_should_not_exist(source=output_pdml_filepath, xpath=xpath)

    def check_tshark_message_for_wrong_value_of_atrribute(
        self, alias, filter, output_pdml_filepath, xpath, attribute, expected_attribute_value
    ):
        """
        :param alias:
        :param filter:
        :param output_pdml_filepath:
        :param xpath:
        :param attribute:
        :param expected_attribute_value:
        :return:
        """
        attribute_value = self.get_attribute_value_from_tshark_message(
            alias=alias, filter=filter, output_pdml_filepath=output_pdml_filepath, xpath=xpath, attribute=attribute
        )
        if attribute_value == expected_attribute_value:
            raise ExecutionFailed(
                message="{} {}  Should be equal".format(attribute_value, expected_attribute_value),
                continue_on_failure=True,
            )

    def set_nsnti_ports_and_packet_defragmnetation_in_wireshark_preferences(self, nsnti_ports, nsnti_defragment):
        """
        :param nsnti_ports:
        :param nsnti_defragment:
        :return:
        """
        sed_ports_cmd = r's/^#\?ntrstr.port.*$/ntrstr.port: {}/g'.format(nsnti_ports)
        sed_defragment_cmd = r's/^#\?ntrstr.defragment.*$/ntrstr.defragment: {}/g'.format(nsnti_defragment)
        set_nsnti_cmd = "sed -i.bak '{};{}' {}".format(
            sed_ports_cmd, sed_defragment_cmd, WIRESHARK_PREFERENCES_FILEPATH
        )
        process_return_code = OperatingSystem().run_and_return_rc(set_nsnti_cmd)
        logger.console("RC CODE: {}".format(process_return_code))
        if process_return_code == 2:
            OperatingSystem().create_file(
                WIRESHARK_PREFERENCES_FILEPATH,
                'ntrstr.port: {}\nntrstr.defragment: {}\n\n'.format(nsnti_ports, nsnti_defragment),
            )

    def get_attribute_value_from_tshark_message(self, alias, filter, output_pdml_filepath, xpath, attribute,
                                                pcap_file_path=None):
        """
        :param alias:
        :param filter:
        :param output_pdml_filepath:
        :param xpath:
        :param attribute:
        :param pcap_file_path: (default None)
        :return:
        """
        self.convert_tshark_to_pdml(alias=alias, packet_filter=filter, output_filepath=output_pdml_filepath,
                                    pcap_file_path=pcap_file_path)
        attribute_value = self._xml_instance.get_element_attribute(
            source=output_pdml_filepath, xpath=xpath, name=attribute
        )
        return attribute_value

    def get_attribute_values_from_tshark_messages(self, alias, filter, output_pdml_filepath, element_xpath,
                                                  attribute_xpath, attribute, pcap_file_path=None):
        """
        :param alias:
        :param filter:
        :param output_pdml_filepath:
        :param element_xpath:
        :param attribute_xpath:
        :param attribute:
        :param pcap_file_path: (default None)
        :return:
        """
        self.convert_tshark_to_pdml(alias=alias, packet_filter=filter, output_filepath=output_pdml_filepath,
                                    pcap_file_path=pcap_file_path)
        elements = self._xml_instance.get_elements(source=output_pdml_filepath, xpath=element_xpath)
        return [self._xml_instance.get_element_attribute(element, attribute, attribute_xpath) for element in elements]

    def get_time_from_tshark_message(self, alias, filter, output_pdml_filepath, pcap_file_path=None):
        """
        :param alias:
        :param filter:
        :param output_pdml_filepath:
        :param pcap_file_path:
        :return:
        """
        message_time = re.search(
            r'\d+:\d\d:\d\d\.\d\d\d\d\d\d',
            str(
                self.get_attribute_values_from_tshark_messages(
                    alias=alias,
                    filter=filter,
                    output_pdml_filepath=output_pdml_filepath,
                    element_xpath='.//packet',
                    attribute_xpath='.//field[@name="timestamp"]',
                    attribute='show',
                    pcap_file_path=pcap_file_path
                )
            ),
        ).group(0)
        return message_time

    def time_between_two_tshark_messages(self, alias, filter1, filter2, output_pdml_filepath1, output_pdml_filepath2,
                                         pcap_file_path=None):
        """
        :param alias:
        :param filter1:
        :param filter2:
        :param output_pdml_filepath1:
        :param output_pdml_filepath2:
        :param pcap_file_path:
        :return:
        """
        time_format = '%H:%M:%S.%f'
        t1 = dt.datetime.strptime(self.get_time_from_tshark_message(alias, filter1, output_pdml_filepath1,
                                                                    pcap_file_path), time_format)
        t2 = dt.datetime.strptime(self.get_time_from_tshark_message(alias, filter2, output_pdml_filepath2,
                                                                    pcap_file_path), time_format)
        delta_time = t2 - t1
        return delta_time.total_seconds()

    def time_between_two_tshark_messages_from_two_files(self, alias1, alias2, filter1, filter2,
                                                        output_pdml_filepath1, output_pdml_filepath2,
                                                        pcap_file_path1=None, pcap_file_path2=None):
        """
        :param alias1:
        :param alias2:
        :param filter1:
        :param filter2:
        :param output_pdml_filepath1:
        :param output_pdml_filepath2:
        :param pcap_file_path1:
        :param pcap_file_path2:
        :return:
        """
        time_format = '%H:%M:%S.%f'
        t1 = dt.datetime.strptime(self.get_time_from_tshark_message(alias1, filter1, output_pdml_filepath1,
                                                                    pcap_file_path1), time_format)
        t2 = dt.datetime.strptime(self.get_time_from_tshark_message(alias2, filter2, output_pdml_filepath2,
                                                                    pcap_file_path2), time_format)
        delta_time = t2 - t1
        return delta_time.total_seconds()

    def get_frame_number_from_tshark_message(self, alias, filter, output_pdml_filepath):
        """
        :param alias:
        :param filter:
        :param output_pdml_filepath:
        :return:
        """
        return self.get_attribute_value_from_tshark_message(
            alias=alias,
            filter=filter,
            output_pdml_filepath=output_pdml_filepath,
            xpath='.//field[@name="frame.number"]',
            attribute='show',
        )

    def get_frame_numbers_from_tshark_messages(self, alias, filter, output_pdml_filepath):
        """
        :param alias:
        :param filter:
        :param output_pdml_filepath:
        :return:
        """
        frame_number = self.get_attribute_values_from_tshark_messages(
            alias=alias,
            filter=filter,
            output_pdml_filepath=output_pdml_filepath,
            element_xpath='.//packet',
            attribute_xpath='.//field[@name="frame.number"]',
            attribute='show',
        )
        return frame_number

    def check_sequence_of_frames_is_ascending(self, frame_sequence):
        """
        :param frame_sequence:
        :return:
        """
        sequence_length = len(frame_sequence)
        if not sequence_length >= 2:
            raise ExecutionFailed(
                message="{} >= {}  Should be true".format(sequence_length, 2), continue_on_failure=True
            )
        for i in range(0, sequence_length - 1):
            if not frame_sequence[i] < frame_sequence[i + 1]:
                raise ExecutionFailed(
                    message="{} < {}  Should be true".format(frame_sequence[i], frame_sequence[i + 1]),
                    continue_on_failure=True,
                )

    def expect_no_packets_in_given_time(self, alias, time):
        """
        :param alias:
        :param time:
        :return:
        """
        ute_tshark_instance = BuiltIn().get_library_instance('ute_tshark')
        try:
            ute_tshark_instance.wait_for_given_packets_number(packet_number=1, alias=alias, timeout=time)
            raise ExecutionFailed(message="Captured packet when expected none")
        except WaitingForPacketTimeout:
            pass
        except Exception as e:
            raise ExecutionFailed(message=e.message)

    def expect_no_specified_packets_in_given_time(self, alias, time, packet_filter=''):
        """
        :param alias:
        :param time:
        :return:
        """
        ute_tshark_instance = BuiltIn().get_library_instance('ute_tshark')
        ute_tshark_instance.start_counting_packets(packet_filter=packet_filter, alias=alias)
        try:
            ute_tshark_instance.wait_for_given_packets_number(packet_number=1, alias=alias, timeout=time)
            raise ExecutionFailed(message="Captured packet when expected none")
        except WaitingForPacketTimeout:
            pass
        except Exception as e:
            raise ExecutionFailed(message=e.message)
        finally:
            ute_tshark_instance.stop_counting_packets(alias=alias)

    def get_mcc_from_element(self, pdml_filepath, xpath_element):
        """
        :param pdml_filepath:
        :param xpath_element:
        :return:
        """
        mcc = self._xml_instance.get_element_attribute(
            source=pdml_filepath, name='show', xpath='{}/field[@name="e212.mcc"]'.format(xpath_element)
        )
        return mcc

    def get_mnc_from_element(self, pdml_filepath, xpath_element):
        """
        :param pdml_filepath:
        :param xpath_element:
        :return:
        """
        mnc = self._xml_instance.get_element_attribute(
            source=pdml_filepath, name='show', xpath='{}/field[@name="e212.mnc"]'.format(xpath_element)
        )
        return mnc

    def get_number_of_handover_preparation_failure_messages_from_pdml(self, pdml_filepath):
        """
        :param pdml_filepath:
        :return:
        """
        tree = ET.parse(pdml_filepath)
        root = tree.getroot()
        numberOfHandoverFailures = len(root.findall(".//*[@showname='HandoverPreparationFailure']"))
        return numberOfHandoverFailures

    def get_number_of_x2_handover_execution_success_messages_from_pdml(self, pdml_filepath):
        """
        :param pdml_filepath:
        :return:
        """
        tree = ET.parse(pdml_filepath)
        root = tree.getroot()
        numberOfHandoverSuccess = len(root.findall(".//*[@showname='SNStatusTransfer']"))
        return numberOfHandoverSuccess

    def get_number_of_s1_handover_execution_success_messages_from_pdml(self, pdml_filepath):
        """
        :param pdml_filepath:
        :return:
        """
        tree = ET.parse(pdml_filepath)
        root = tree.getroot()
        numberOfHandoverSuccess = len(root.findall(".//*[@showname='radioNetwork: successful-handover (2)']"))
        return numberOfHandoverSuccess

    def get_ue_crnti_from_tshark_rrc_connection_setup_message(self, ue_id, tshark_alias, output_dir=None):
        """
        :param ue_id:
        :param tshark_alias:
        :param output_dir:
        :return:
        """
        if not output_dir:
            output_dir = ta5g_interface_tools().get_robot_output_dir()
        self.convert_tshark_to_pdml(
            packet_filter='(iphy.ue_id=={}) && (lte-rrc.rrcConnectionSetup_element)'.format(ue_id),
            output_filepath='{}{}rrc_connection_setup_ue_id_{}.pdml'.format(output_dir, os.sep, ue_id),
            alias=tshark_alias,
        )
        list_packet_num = self._xml_instance.evaluate_xpath(
            source='{}{}rrc_connection_setup_ue_id_{}.pdml'.format(output_dir, os.sep, ue_id),
            expression='.//field[@name="iphy.c_rnti"]/@showname',
        )
        crnti_hex = list_packet_num[0].split(' ')[-1]
        crnti_dec = int(crnti_hex, 0)
        return crnti_dec

    def get_ue_crnti_from_tshark_rrc_connection_reestablishment_message(self, ue_id, tshark_alias, output_dir=None):
        """
        :param ue_id:
        :param tshark_alias:
        :param output_dir:
        :return:
        """
        if not output_dir:
            output_dir = ta5g_interface_tools().get_robot_output_dir()
        self.convert_tshark_to_pdml(
            packet_filter='(iphy.ue_id=={}) && lte-rrc.rrcConnectionReestablishment_element'.format(ue_id),
            output_filepath='{}{}rrc_reestablishment_ue_id_{}.pdml'.format(output_dir, os.sep, ue_id),
            alias=tshark_alias,
        )
        list_packet_num = self._xml_instance.evaluate_xpath(
            source='{}{}rrc_reestablishment_ue_id_{}.pdml'.format(output_dir, os.sep, ue_id),
            expression='.//field[@name="iphy.c_rnti"]/@showname',
        )
        crnti_hex = list_packet_num[0].split(' ')[-1]
        crnti_dec = BuiltIn().convert_to_integer(crnti_hex)
        return crnti_dec

    def with_message_capture(self, interface, keyword, *args):
        """
        :param interface:    [string] one interface or seq of interfaces e.g. 'eth1, eth2, eth3'
        :param keyword:
        :param args:
        :return:              alias
        """
        captured_messages_alias = TsharkStart().start_tshark_for_custom_interface(eth_interface=interface)
        built_in = BuiltIn()
        built_in.run_keyword(keyword, *args)
        built_in.sleep('5s')
        ute_tshark = BuiltIn().get_library_instance('ute_tshark')
        ute_tshark.stop_capturing(alias=captured_messages_alias)
        return captured_messages_alias

    def with_message_multiple_capture(self, interfaces, keyword, *args):
        """
        :param interface:    [string] one interface or seq of interfaces e.g. 'eth1,eth2,eth3'
        :param keyword:
        :param args:
        :return:              dict of aliases
        """
        captured_messages_alias_dict = {}
        interface_list = interfaces.split(',')
        for iface in interface_list:
            captured_messages_alias_dict[iface] = TsharkStart().start_tshark_for_custom_interface(eth_interface=iface)
        built_in = BuiltIn()
        built_in.run_keyword(keyword, *args)
        built_in.sleep('3s')
        ute_tshark = BuiltIn().get_library_instance('ute_tshark')
        for alias in list(captured_messages_alias_dict.values()):
            ute_tshark.stop_capturing(alias=alias)
        return captured_messages_alias_dict

